/**
 * Index maintenance on issue and comment writes.
 *
 * Owner C implements `@/server/services/search-service`.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import { rateLimitState } from "../server/_support/doubles/misc";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  tenant = await createTenant("searchsvc", "enterprise");
});

afterAll(() => {
  detach();
  cleanup();
});

afterEach(() => {
  rateLimitState.allowed = true;
  rateLimitState.remaining = 100;
});

describe("services/search-service", () => {
  it("indexes an issue and a comment on creation", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Zulu index target" }),
    );
    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Yankee index target",
      parentId: null,
      mentionedUserIds: [],
    });

    const issueHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Zulu",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(issueHits.total).toBe(1);
    expect(issueHits.items[0]).toMatchObject({ kind: "issue", id: issue.id });

    const commentHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Yankee",
      kinds: ["comment"],
      limit: 25,
      cursor: null,
    });
    expect(commentHits.total).toBe(1);
    expect(commentHits.items[0]).toMatchObject({ kind: "comment", id: comment.id });
  });

  it("re-indexes an updated issue in place", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Original Title Marker" }),
    );

    await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      title: "Updated Title Marker",
    });

    const stale = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Original Title Marker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(stale.total).toBe(0);

    const fresh = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Updated Title Marker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(fresh.total).toBe(1);
    expect(fresh.items[0]).toMatchObject({ id: issue.id });
  });

  it("drops an archived issue from the index", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "ArchiveIndexMarker" }),
    );

    const before = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "ArchiveIndexMarker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(before.total).toBe(1);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    const after = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "ArchiveIndexMarker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(after.total).toBe(0);
  });

  it("never returns another tenant's rows", async () => {
    const other = await createTenant("searchsvcother", "growth");
    await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "CrossTenantMarker" }),
    );

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "CrossTenantMarker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });

    expect(hits.total).toBe(0);
    expect(hits.items).toHaveLength(0);
  });

  it("falls back to plain matching when advanced_search is off", async () => {
    // A "growth" workspace does not include advanced_search.
    const plain = await createTenant("searchsvcplain", "growth");
    await issueService.createIssue(
      plain.actors.member,
      issueInput(plain.org.id, plain.project.id, { title: "PlainMatchWorks" }),
    );

    await expect(
      searchService.search(plain.actors.member, {
        orgId: plain.org.id,
        q: "PlainMatchWorks",
        kinds: ["issue"],
        limit: 25,
        cursor: null,
      }),
    ).resolves.toMatchObject({ total: 1 });
  });

  it("rate-limits search queries per organization", async () => {
    rateLimitState.allowed = false;

    await expect(
      searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "anything",
        kinds: ["issue"],
        limit: 25,
        cursor: null,
      }),
    ).rejects.toThrow(/rate limit/i);
  });
});
import { describe, expect, it } from "vitest";
import {
  describeQuery,
  parseSearchQuery,
} from "@/components/domain/search/query-syntax";

describe("query-syntax/parseSearchQuery", () => {
  it("treats everything as free text when the flag is off", () => {
    const parsed = parseSearchQuery("kind:comment deploy", false);
    expect(parsed.text).toBe("kind:comment deploy");
    expect(parsed.kinds).toEqual(["issue"]);
  });

  it("extracts kind tokens when the flag is on", () => {
    const parsed = parseSearchQuery("kind:comment deploy", true);
    expect(parsed.text).toBe("deploy");
    expect(parsed.kinds).toEqual(["comment"]);
  });

  it("accepts the plural and the in: alias", () => {
    expect(parseSearchQuery("in:projects roadmap", true).kinds).toEqual([
      "project",
    ]);
  });

  it("collects several kinds", () => {
    expect(
      parseSearchQuery("kind:issue kind:comment flaky", true).kinds,
    ).toEqual(["issue", "comment"]);
  });

  it("extracts a project filter", () => {
    const parsed = parseSearchQuery("project:prj_7 latency", true);
    expect(parsed.projectId).toBe("prj_7");
    expect(parsed.text).toBe("latency");
  });

  it("reports tokens it did not understand instead of searching for them", () => {
    const parsed = parseSearchQuery("author:ada bug", true);
    expect(parsed.unknownTokens).toEqual(["author:ada"]);
    expect(parsed.text).toBe("bug");
  });

  it("keeps a leading colon as ordinary text", () => {
    expect(parseSearchQuery(":wat", true).text).toBe(":wat");
  });

  it("falls back to the default kind when only syntax was typed", () => {
    expect(parseSearchQuery("project:prj_7", true).kinds).toEqual(["issue"]);
  });
});

describe("query-syntax/describeQuery", () => {
  it("summarises what the parser understood", () => {
    const parsed = parseSearchQuery("kind:comment project:prj_1 nope:x hi", true);
    const description = describeQuery(parsed);
    expect(description).toContain("searching comment");
    expect(description).toContain("in project prj_1");
    expect(description).toContain("ignoring nope:x");
  });
});
"use server";

/**
 * Search Server Action used by the command palette and the search page.
 *
 * Owner D. Searching across comments as well as issues is an `advanced_search`
 * capability. The service narrows the requested kinds when the flag is off, so
 * this action passes the request straight through and the palette degrades
 * instead of erroring.
 *
 * Must call (do not reimplement): searchQuerySchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { can } from "@/lib/permissions";
import { searchQuerySchema, type SearchQueryInput } from "@/schemas/search";
import { search, type SearchHit } from "@/server/services/search-service";
import type { ActionResult } from "@/types/api";

const run = withAction<typeof searchQuerySchema, SearchHit[]>(
  searchQuerySchema,
  async (raw, actor) => {
    const input = raw as SearchQueryInput;

    if (!can(actor, "org:read", { kind: "organization", orgId: input.orgId })) {
      throw new ForbiddenActionError("org:read");
    }

    const page = await search(actor, input);
    return [...page.items];
  },
  { requireOrg: true },
);

export async function searchAction(raw: unknown): Promise<ActionResult<SearchHit[]>> {
  return run(raw);
}
/**
 * JSON search endpoint used by the command palette.
 *
 * Owner D. The palette hits this route rather than the Server Action because it
 * fires on every keystroke and wants a plain cancellable fetch. Like
 * `searchAction` it asks for every kind and leaves the plan gating to the
 * service, so neither entry point can be the lenient one.
 *
 * Must call (do not reimplement): can, isEnabled
 */

import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getActor } from "@/lib/actor";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { searchQuerySchema } from "@/schemas/search";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { search } from "@/server/services/search-service";

export const dynamic = "force-dynamic";

const PALETTE_LIMIT = 10;

export async function GET(request: Request): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    const q = url.searchParams.get("q");

    if (orgSlug === null || q === null) {
      return failure("validation_failed", "orgSlug and q are required.");
    }

    const actor = await getActor(orgSlug);

    if (!can(actor, "org:read", { kind: "organization", orgId: actor.orgId })) {
      return failure("forbidden", "You cannot search this organization.");
    }

    const { organization } = await getOrganizationSummary(actor, actor.orgId);
    const context = buildFlagContext(actor, organization);

    if (!isEnabled("command_palette", context)) {
      return failure("forbidden", "The command palette is not enabled here.");
    }

    const parsed = searchQuerySchema.safeParse({
      orgId: actor.orgId,
      q,
      kinds: ["issue", "comment", "project"],
      limit: PALETTE_LIMIT,
    });
    if (!parsed.success) {
      return failure("validation_failed", "Bad search query.");
    }

    const page = await search(actor, parsed.data);
    return Response.json({ items: page.items, total: page.total });
  } catch (error) {
    return errorResponse(error);
  }
}
