import { describe, expect, it } from "vitest";
import {
  describeQuery,
  parseSearchQuery,
} from "@/components/domain/search/query-syntax";

describe("query-syntax/parseSearchQuery", () => {
  it("treats everything as free text when the flag is off", () => {
    const parsed = parseSearchQuery("kind:comment deploy", false);
    expect(parsed.text).toBe("kind:comment deploy");
    expect(parsed.kinds).toEqual(["issue"]);
  });

  it("extracts kind tokens when the flag is on", () => {
    const parsed = parseSearchQuery("kind:comment deploy", true);
    expect(parsed.text).toBe("deploy");
    expect(parsed.kinds).toEqual(["comment"]);
  });

  it("accepts the plural and the in: alias", () => {
    expect(parseSearchQuery("in:projects roadmap", true).kinds).toEqual([
      "project",
    ]);
  });

  it("collects several kinds", () => {
    expect(
      parseSearchQuery("kind:issue kind:comment flaky", true).kinds,
    ).toEqual(["issue", "comment"]);
  });

  it("extracts a project filter", () => {
    const parsed = parseSearchQuery("project:prj_7 latency", true);
    expect(parsed.projectId).toBe("prj_7");
    expect(parsed.text).toBe("latency");
  });

  it("reports tokens it did not understand instead of searching for them", () => {
    const parsed = parseSearchQuery("author:ada bug", true);
    expect(parsed.unknownTokens).toEqual(["author:ada"]);
    expect(parsed.text).toBe("bug");
  });

  it("keeps a leading colon as ordinary text", () => {
    expect(parseSearchQuery(":wat", true).text).toBe(":wat");
  });

  it("falls back to the default kind when only syntax was typed", () => {
    expect(parseSearchQuery("project:prj_7", true).kinds).toEqual(["issue"]);
  });
});

describe("query-syntax/describeQuery", () => {
  it("summarises what the parser understood", () => {
    const parsed = parseSearchQuery("kind:comment project:prj_1 nope:x hi", true);
    const description = describeQuery(parsed);
    expect(description).toContain("searching comment");
    expect(description).toContain("in project prj_1");
    expect(description).toContain("ignoring nope:x");
  });
});
"use server";

/**
 * Search Server Action used by the command palette and the search page.
 *
 * Owner D. Searching across comments as well as issues is an `advanced_search`
 * capability. The service narrows the requested kinds when the flag is off, so
 * this action passes the request straight through and the palette degrades
 * instead of erroring.
 *
 * Must call (do not reimplement): searchQuerySchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { can } from "@/lib/permissions";
import { searchQuerySchema, type SearchQueryInput } from "@/schemas/search";
import { search, type SearchHit } from "@/server/services/search-service";
import type { ActionResult } from "@/types/api";

const run = withAction<typeof searchQuerySchema, SearchHit[]>(
  searchQuerySchema,
  async (raw, actor) => {
    const input = raw as SearchQueryInput;

    if (!can(actor, "org:read", { kind: "organization", orgId: input.orgId })) {
      throw new ForbiddenActionError("org:read");
    }

    const page = await search(actor, input);
    return [...page.items];
  },
  { requireOrg: true },
);

export async function searchAction(raw: unknown): Promise<ActionResult<SearchHit[]>> {
  return run(raw);
}
/**
 * JSON search endpoint used by the command palette.
 *
 * Owner D. The palette hits this route rather than the Server Action because it
 * fires on every keystroke and wants a plain cancellable fetch. Like
 * `searchAction` it asks for every kind and leaves the plan gating to the
 * service, so neither entry point can be the lenient one.
 *
 * Must call (do not reimplement): can, isEnabled
 */

import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getActor } from "@/lib/actor";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { searchQuerySchema } from "@/schemas/search";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { search } from "@/server/services/search-service";

export const dynamic = "force-dynamic";

const PALETTE_LIMIT = 10;

export async function GET(request: Request): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    const q = url.searchParams.get("q");

    if (orgSlug === null || q === null) {
      return failure("validation_failed", "orgSlug and q are required.");
    }

    const actor = await getActor(orgSlug);

    if (!can(actor, "org:read", { kind: "organization", orgId: actor.orgId })) {
      return failure("forbidden", "You cannot search this organization.");
    }

    const { organization } = await getOrganizationSummary(actor, actor.orgId);
    const context = buildFlagContext(actor, organization);

    if (!isEnabled("command_palette", context)) {
      return failure("forbidden", "The command palette is not enabled here.");
    }

    const parsed = searchQuerySchema.safeParse({
      orgId: actor.orgId,
      q,
      kinds: ["issue", "comment", "project"],
      limit: PALETTE_LIMIT,
    });
    if (!parsed.success) {
      return failure("validation_failed", "Bad search query.");
    }

    const page = await search(actor, parsed.data);
    return Response.json({ items: page.items, total: page.total });
  } catch (error) {
    return errorResponse(error);
  }
}
